INSERT OR REPLACE INTO source_documents (source_id, pack_id, species, kind, scope, source_url, final_url, retrieved_at, raw_file, text_file, bytes) VALUES ('deer-big-game-season','oklahoma-large-game','deer','species-regulations','Oklahoma deer big-game season','https://www.wildlifedepartment.com/hunting/regs/deer-big-game-season','https://www.wildlifedepartment.com/hunting/regs/deer-big-game-season','2026-08-21T03:32:09.614609+00:00','data/oklahoma/raw/deer-big-game-season.html','data/oklahoma/raw/deer-big-game-season.txt','96157');
INSERT OR REPLACE INTO rule_records (rule_id, source_id, species, title, start_date, end_date, source_text, review_status, effective_year, created_at) VALUES ('deer-big-game-season:1','deer-big-game-season','deer','Deer Archery','Oct 1, 2026','Jan 15, 2027','Six : no more than two may be antlered. All deer taken during the deer archery season count toward the hunter’s combined season limit of six deer.','captured-unreviewed','2026','2026-08-21T03:32:09.614609+00:00');
INSERT OR REPLACE INTO rule_records (rule_id, source_id, species, title, start_date, end_date, source_text, review_status, effective_year, created_at) VALUES ('deer-big-game-season:2','deer-big-game-season','deer','Youth Deer Gun','Oct 16, 2026','Oct 18, 2026','Two : no more than one may be antlered. Harvest of antlerless mule deer is prohibited. All deer taken during the youth deer gun season are included in the hunter’s combined season limit of six deer, but are not included as part of the hunter’s regular deer gun season limit of four deer. Youth Deer Gun Age Requirements 17 years old and younger. All youth hunters must be accompanied by an adult 18 years of age or older with current hunting license.','captured-unreviewed','2026','2026-08-21T03:32:09.614609+00:00');
INSERT OR REPLACE INTO rule_records (rule_id, source_id, species, title, start_date, end_date, source_text, review_status, effective_year, created_at) VALUES ('deer-big-game-season:3','deer-big-game-season','deer','Deer Muzzleloader','Oct 24, 2026','Nov 1, 2026','Four : no more than one may be antlered. Harvest of antlerless mule deer is prohibited. Antlerless harvest limits are set by zone. Zone 1: One antlerless. Zones 2, 7 & 8: four antlerless. Zones 3, 4, 5, 6 & 9: two antlerless. Zone 10: one antlerless. See Antlerless Deer Zones for the Antlerless Deer Zones map. All deer taken during the deer muzzleloader season count toward the hunter’s combined season limit of six deer.','captured-unreviewed','2026','2026-08-21T03:32:09.614609+00:00');
INSERT OR REPLACE INTO rule_records (rule_id, source_id, species, title, start_date, end_date, source_text, review_status, effective_year, created_at) VALUES ('deer-big-game-season:4','deer-big-game-season','deer','Deer Gun','Nov 21, 2026','Dec 6, 2026','Four : no more than one may be antlered. Harvest of antlerless mule deer is prohibited. Antlerless harvest limits are set by zone. Zone 1: one antlerless. Zones 2, 7 & 8: four antlerless. Zones 3, 4, 5, 6 & 9: two antlerless. Zone 10: one antlerless. See Antlerless Deer Zones for the Antlerless Deer Zones map. All deer taken during the deer gun season count toward the hunter’s combined season limit of six deer.','captured-unreviewed','2026','2026-08-21T03:32:09.614609+00:00');
INSERT OR REPLACE INTO rule_records (rule_id, source_id, species, title, start_date, end_date, source_text, review_status, effective_year, created_at) VALUES ('deer-big-game-season:5','deer-big-game-season','deer','Holiday Antlerless Deer Gun','Dec 18, 2026','Dec 31, 2026','Two : antlerless only. Harvest of antlerless mule deer is prohibited. Deer taken during the holiday antlerless deer gun season do not count toward the hunter’s combined season limit of six deer.','captured-unreviewed','2026','2026-08-21T03:32:09.614609+00:00');
