INSERT OR REPLACE INTO source_documents (source_id, pack_id, species, kind, scope, source_url, final_url, retrieved_at, raw_file, text_file, bytes) VALUES ('antelope-big-game-season','oklahoma-large-game','antelope','species-regulations','Oklahoma antelope big-game season','https://www.wildlifedepartment.com/hunting/regs/antelope-big-game-season','https://www.wildlifedepartment.com/hunting/regs/antelope-big-game-season','2026-08-21T03:32:09.614609+00:00','data/oklahoma/raw/antelope-big-game-season.html','data/oklahoma/raw/antelope-big-game-season.txt','85112');
INSERT OR REPLACE INTO rule_records (rule_id, source_id, species, title, start_date, end_date, source_text, review_status, effective_year, created_at) VALUES ('antelope-big-game-season:1','antelope-big-game-season','antelope','Antelope Archery','Oct 1, 2026','Oct 14, 2026','Two : no more than one may be a buck. Archery antelope are not bonus and count toward the combined season limit.','captured-unreviewed','2026','2026-08-21T03:32:09.614609+00:00');
INSERT OR REPLACE INTO rule_records (rule_id, source_id, species, title, start_date, end_date, source_text, review_status, effective_year, created_at) VALUES ('antelope-big-game-season:2','antelope-big-game-season','antelope','Antelope Gun (either sex, draw only, landowner/controlled hunt permits)','Sep 3, 2026','Sep 6, 2026','Antelope Gun (either sex, draw only, landowner/controlled hunt permits) Sep 3, 2026 - Sep 6, 2026','captured-unreviewed','2026','2026-08-21T03:32:09.614609+00:00');
INSERT OR REPLACE INTO rule_records (rule_id, source_id, species, title, start_date, end_date, source_text, review_status, effective_year, created_at) VALUES ('antelope-big-game-season:3','antelope-big-game-season','antelope','Antelope Gun (doe only, draw only, controlled hunt permit only)','Sep 7, 2026','Sep 16, 2026','Antelope Gun (doe only, draw only, controlled hunt permit only) Sep 7, 2026 - Sep 16, 2026','captured-unreviewed','2026','2026-08-21T03:32:09.614609+00:00');
INSERT OR REPLACE INTO rule_records (rule_id, source_id, species, title, start_date, end_date, source_text, review_status, effective_year, created_at) VALUES ('antelope-big-game-season:4','antelope-big-game-season','antelope','Antelope Gun (doe only, draw only, landowner permit only)','Nov 28, 2026','Jan 15, 2027','Antelope gun hunting is only available through the Department’s controlled hunts program or through the Landowner Permit Drawing (see wildlifedepartment.com.) Gun Limit Two : no more than one may be a buck. Antelope taken through controlled hunts or landowner permit are not bonus and count toward the combined season limit. Legal sex and specific season dates will be designated on the controlled hunt or landowner permit.','captured-unreviewed','2026','2026-08-21T03:32:09.614609+00:00');
